import numpy as np
from sklearn.linear_model import LinearRegression

def area_only_rmse():
    m = LinearRegression().fit(X_train[['area_m2']], y_train)
    return float(np.sqrt(np.mean((y_test - m.predict(X_test[['area_m2']])) ** 2)))

import numpy as np
from sklearn.ensemble import RandomForestRegressor
from sklearn.linear_model import LinearRegression

def forest_rmse():
    m = RandomForestRegressor(300, min_samples_leaf=3, random_state=0).fit(X_train, y_train)
    return float(np.sqrt(np.mean((y_test - m.predict(X_test)) ** 2)))

def log_rmse():
    m = LinearRegression().fit(X_train, np.log(y_train))
    return float(np.sqrt(np.mean((y_test - np.exp(m.predict(X_test))) ** 2)))
